#!/usr/bin/env bash
set -euo pipefail

PROJECT="ios/Runner.xcodeproj/project.pbxproj"
test -f "$PROJECT"

python3 - <<'PY'
from pathlib import Path
import re

path = Path("ios/Runner.xcodeproj/project.pbxproj")
text = path.read_text()
# Unsigned CI artifacts must not trigger automatic provisioning. Apply the
# settings at the Xcode build-configuration level so they reach every target
# configuration generated by Flutter.
pattern = re.compile(r"(buildSettings = \{)(.*?)(\n\s*\};)", re.S)
count = 0

def patch(match):
    global count
    body = match.group(2)
    settings = (
        '\n\t\t\t\tCODE_SIGNING_ALLOWED = NO;'
        '\n\t\t\t\tCODE_SIGNING_REQUIRED = NO;'
        '\n\t\t\t\tCODE_SIGN_IDENTITY = "";'
        '\n\t\t\t\tPROVISIONING_PROFILE_SPECIFIER = "";'
        '\n\t\t\t\tDEVELOPMENT_TEAM = "";'
        '\n\t\t\t\tCODE_SIGN_STYLE = Manual;'
    )
    # Avoid duplicate entries if CI setup is rerun.
    for key in ("CODE_SIGNING_ALLOWED", "CODE_SIGNING_REQUIRED",
                "CODE_SIGN_IDENTITY", "PROVISIONING_PROFILE_SPECIFIER",
                "DEVELOPMENT_TEAM", "CODE_SIGN_STYLE"):
        body = re.sub(rf"^\s*{key} = .*?;\s*$", "", body, flags=re.M)
    count += 1
    return match.group(1) + body + settings + match.group(3)

patched = pattern.sub(patch, text)
if count == 0:
    raise SystemExit("No Xcode build configurations found; refusing to continue.")
path.write_text(patched)
print(f"Disabled signing/provisioning in {count} Xcode build configurations for unsigned CI builds.")
PY

grep -q 'CODE_SIGNING_ALLOWED = NO;' "$PROJECT"
